from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, ListFlowable, ListItem
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.units import inch
import pandas as pd
from analysis import load_data, cluster_data
clients, properties, data = load_data()
clustered, metrics = cluster_data(data)
profile = clustered.groupby('cluster').agg(buyers=('client_id','count'), mean_age=('age','mean'), satisfaction=('satisfaction_score','mean'), investment_pct=('acquisition_purpose',lambda s:(s=='Investment').mean()*100), loan_pct=('loan_applied',lambda s:(s=='Yes').mean()*100), avg_purchase=('avg_purchase_price','mean'), sold=('sold_properties','sum')).round(2)
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='TitleCenter', parent=styles['Title'], alignment=TA_CENTER, fontSize=18, leading=22, spaceAfter=12)); styles.add(ParagraphStyle(name='Small', parent=styles['BodyText'], fontSize=8, leading=10))
story=[]
story += [Paragraph('Machine Learning Based Buyer Segmentation and Investment Profiling for Real Estate Market Intelligence', styles['TitleCenter']), Paragraph('Project Report | Unified Mentor / Parcl Co. Limited', styles['Heading2']), Spacer(1,8)]
story += [Paragraph('1. Executive Summary', styles['Heading1']), Paragraph(f'This project explores buyer segmentation using client demographics, acquisition purpose, financing indicators, satisfaction scores, and linked sold-property activity. The supplied datasets contain {len(clients):,} client records and {len(properties):,} property records. K-Means was run with four clusters as directed by the project brief, with a sampled Hierarchical Clustering comparison. The K-Means sampled silhouette score was {metrics["kmeans_silhouette_sample"]:.3f}; the Hierarchical sample score was {metrics["hierarchical_silhouette_sample"]:.3f}. These modest values suggest the segments overlap and should be treated as exploratory rather than definitive market categories.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('2. Problem Statement and Objectives', styles['Heading1']), Paragraph('The project brief states that Parcl lacks a data-driven understanding of buyer types, investment motivations across demographics, geographic differences in investment behaviour, and customer financing patterns. Objectives are to clean and combine the datasets, explore patterns, cluster buyers, compare clustering approaches, and present results in an interactive dashboard.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('3. Data Description and Preparation', styles['Heading1']), Paragraph('clients.csv contains client_id, client_type, first_name, last_name, date_of_birth, gender, country, region, acquisition_purpose, satisfaction_score, loan_applied, and referral_channel. properties.csv contains listing_id, tower_number, transaction_date, unit_category, unit_number, floor_area_sqft, sale_price, listing_status, and client_ref. Client data had no missing values in the supplied file. The property client_ref field had 2,695 missing values; these records are not attributed to a client during aggregation. Sale prices were converted from currency-formatted text to numeric values. Sold property records were aggregated by client_ref and left-joined to client profiles. Age is approximated as of 12 October 2026.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('4. Methodology', styles['Heading1']), Paragraph('Numeric features (age, satisfaction score, sold-property count, total purchase value, average purchase price, average area, and number of property types) were median-imputed and standardized. Categorical features (client type, gender, country, region, acquisition purpose, loan application, and referral channel) were imputed with the most frequent value and one-hot encoded. K-Means used k=4, random_state=42, and n_init=10. Hierarchical clustering with Ward linkage was evaluated on a reproducible sample of up to 500 records. Silhouette scores were estimated on samples to manage runtime.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('5. Results', styles['Heading1']), Paragraph('Cluster IDs are algorithm-generated labels and do not automatically correspond to the example buyer types listed in the project brief. The table below summarizes observed profiles; interpret them from measured values rather than assigning unsupported labels such as “Global Investor” or “Luxury Investor.”', styles['BodyText']), Spacer(1,6)]
data_tbl=[['Cluster','Buyers','Mean age','Satisfaction','Investment purpose','Loan applied','Avg. purchase value','Sold properties']]
for i,r in profile.iterrows(): data_tbl.append([f'C{i+1}',str(int(r.buyers)),f'{r.mean_age:.1f}',f'{r.satisfaction:.2f}',f'{r.investment_pct:.1f}%',f'{r.loan_pct:.1f}%',f'${r.avg_purchase:,.0f}',str(int(r.sold))])
t=Table(data_tbl, repeatRows=1, colWidths=[0.55*inch,0.55*inch,0.65*inch,0.72*inch,0.85*inch,0.72*inch,1.05*inch,0.75*inch]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dbeafe')),('GRID',(0,0),(-1,-1),0.4,colors.grey),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),7),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f8fafc')]),('LEFTPADDING',(0,0),(-1,-1),4),('RIGHTPADDING',(0,0),(-1,-1),4)])); story += [t, Spacer(1,8)]
story += [Paragraph('Key observations', styles['Heading2']), Paragraph(f'• Cluster C2 is the smallest segment ({int(profile.iloc[1].buyers)} clients) and has the highest mean age ({profile.iloc[1].mean_age:.1f}) and satisfaction ({profile.iloc[1].satisfaction:.2f}).\n• Cluster C4 has the highest average purchase value among clients with linked sold-property records (${profile.iloc[3].avg_purchase:,.0f}).\n• Investment-purpose buyers make up approximately 29.8%–34.7% of each cluster, so acquisition purpose alone does not sharply separate these clusters.\n• The K-Means silhouette score ({metrics["kmeans_silhouette_sample"]:.3f}) is low, indicating substantial overlap; further feature selection and cluster-count tuning may improve interpretability.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('6. Dashboard Design', styles['Heading1']), Paragraph('The Streamlit dashboard provides a buyer-segmentation overview, investment-behaviour charts, geographic analysis, descriptive cluster profiles, client-level records, and CSV export. Sidebar controls filter by country, region, acquisition purpose, and client type. The dashboard is intended for exploratory analysis and does not make investment recommendations for individual buyers.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('7. Recommendations', styles['Heading1']), Paragraph('1. Treat the four clusters as exploratory segments and validate them with business stakeholders before using them in marketing campaigns.\n2. Investigate the very small C2 cluster and check whether it reflects a meaningful buyer group or a feature-scaling / categorical-encoding effect.\n3. Improve data linkage for property records with missing client_ref values before drawing client-level purchase conclusions.\n4. Evaluate alternative feature sets, k values, and distance metrics; report silhouette scores alongside business interpretability.\n5. Use country, region, acquisition purpose, and client type filters to support targeted analysis, while avoiding claims of causation.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('8. Limitations', styles['Heading1']), Paragraph('The dataset does not include an explicit income field, although the project brief’s suggested segment descriptions refer to income and “large investments.” Those labels cannot be verified from the available fields. Property linkage is incomplete for 2,695 rows. The silhouette scores are sampled and should not be compared as a formal model-selection study without consistent validation procedures. The report is based on the supplied datasets and project brief.', styles['BodyText']), Spacer(1,8)]
story += [Paragraph('9. Conclusion', styles['Heading1']), Paragraph('The workflow combines client profiles with sold-property activity and demonstrates an end-to-end approach to buyer segmentation, model comparison, and interactive market analysis. Results show differences in age, satisfaction, and average purchase value across the four clusters, but the low silhouette score indicates that the current segments overlap. Better client-property linkage, feature refinement, and business validation are recommended before operational use.', styles['BodyText']), Spacer(1,10), Paragraph('Reproducibility: run `python analysis.py` to regenerate cluster outputs, and `streamlit run app.py` to launch the dashboard.', styles['Small'])]
SimpleDocTemplate('Detailed_Project_Report.pdf', pagesize=A4, rightMargin=38,leftMargin=38,topMargin=38,bottomMargin=38).build(story)
